mapper.select:
SELECT b.frozen_member::text AS frozen_member
  FROM public.nw_runtime_agent_run_bindings b
 WHERE b.tenant_id=#{owner.sessionRef.tenantId.value}
   AND b.session_id=#{owner.sessionRef.sessionId}
   AND b.target_kind=#{owner.target.kind}
   AND b.target_id=#{owner.target.id}
   AND b.end_user_id IS NOT DISTINCT FROM NULL#{owner.requireUser.value}
   AND b.actor_agent_id=#{agent}
   AND (b.input_id=#{input} OR 'input:'||b.run_id=#{input})

SELECT tenant_id, session_id, agent_id, end_user_id, input_id, snapshot_id, generation, snapshot_data, target_kind,
       target_id FROM public.nw_runtime_session_capabilities
WHERE tenant_id=#{owner.sessionRef.tenantId.value}
  AND target_kind=#{owner.target.kind} AND target_id=#{owner.target.id}
  AND session_id=#{owner.sessionRef.sessionId} AND input_id=#{input}
